      super.init(viewMode: .sourceAccurate)
    }

    override func visit(_ node: StringLiteralExprSyntax) -> SyntaxVisitorContinueKind {
      if let representedLiteralValue = node.representedLiteralValue,
        representedLiteralValue == string
